<!-- Client-Side Form Interaction & Micro-Interaction Script -->
<script>
    (function() {
      const form = document.getElementById('dsam-rfq-form');
      const submitBtn = document.getElementById('submit-rfq-button');
      const formCard = document.getElementById('rfq-form-card');
      const successContainer = document.getElementById('rfq-success-container');
      const resetBtn = document.getElementById('reset-form-btn');
      
      // Fields & Errors
      const nameField = document.getElementById('client-name');
      const phoneField = document.getElementById('client-phone');
      const emailField = document.getElementById('client-email');
      
      const nameError = document.getElementById('name-error');
      const phoneError = document.getElementById('phone-error');
      const emailError = document.getElementById('email-error');

      // Dropzone & File Handling
      const dropzone = document.getElementById('dropzone-area');
      const fileInput = document.getElementById('sample-file-input');
      const previewCard = document.getElementById('file-preview-card');
      const removeFileBtn = document.getElementById('remove-file-btn');
      const replaceFileBtn = document.getElementById('replace-file-btn');

      // Summary Placeholders in Success Card
      const summaryProduct = document.getElementById('summary-product');
      const summaryMaterial = document.getElementById('summary-material');
      const summaryContact = document.getElementById('summary-contact');
      const dynamicRfqId = document.getElementById('dynamic-rfq-id');
      const quoteItems = document.getElementById('quote-items');
      const addQuoteItem = document.getElementById('add-quote-item');
      let itemCount = quoteItems ? document.querySelectorAll('.quote-item').length : 1;

      function refreshItemLabels() {
        document.querySelectorAll('.quote-item').forEach((item, index) => {
          item.dataset.itemIndex = index;
          const heading = item.querySelector('h2');
          const counter = item.querySelector('.font-tech-data');
          if (heading) heading.textContent = 'Specification Item ' + (index + 1);
          if (counter) counter.textContent = (index + 1) + ' of 10';
        });
      }

      if (addQuoteItem && quoteItems) {
        addQuoteItem.addEventListener('click', function() {
          if (itemCount >= 10) return;
          const source = quoteItems.querySelector('.quote-item');
          const clone = source.cloneNode(true);
          const index = itemCount;
          clone.querySelectorAll('[name]').forEach((field) => {
            field.name = field.name.replace(/items\[0\]/g, 'items[' + index + ']');
            if (field.type === 'radio') field.checked = field.value === 'With Print';
            else if (field.tagName === 'SELECT') field.selectedIndex = 0;
            else field.value = '';
          });
          clone.querySelectorAll('[id]').forEach((field) => {
            field.id = field.id.replace(/-0$/, '-' + index);
          });
          const removeButton = document.createElement('button');
          removeButton.type = 'button';
          removeButton.className = 'remove-quote-item rounded p-1 text-error hover:bg-error-container';
          removeButton.title = 'Remove specification';
          removeButton.innerHTML = '<span class="material-symbols-outlined text-lg">delete</span>';
          clone.querySelector('h2')?.parentElement?.parentElement?.appendChild(removeButton);
          removeButton.addEventListener('click', function() {
            clone.remove();
            itemCount -= 1;
            refreshItemLabels();
            addQuoteItem.classList.remove('hidden');
          });
          quoteItems.insertBefore(clone, addQuoteItem);
          itemCount += 1;
          refreshItemLabels();
          if (itemCount >= 10) addQuoteItem.classList.add('hidden');
        });
      }

      if (submitBtn) {
        submitBtn.addEventListener('click', function(e) {
          e.preventDefault();
          let isValid = true;

          // Validate Name
          if (!nameField.value.trim()) {
            nameError.classList.remove('hidden');
            nameError.classList.add('flex');
            nameField.classList.add('bg-error-container/20');
            isValid = false;
          } else {
            nameError.classList.add('hidden');
            nameError.classList.remove('flex');
            nameField.classList.remove('bg-error-container/20');
          }

          // Validate Phone
          if (!phoneField.value.trim() || phoneField.value.trim().length < 7) {
            phoneError.classList.remove('hidden');
            phoneError.classList.add('flex');
            phoneField.classList.add('bg-error-container/20');
            isValid = false;
          } else {
            phoneError.classList.add('hidden');
            phoneError.classList.remove('flex');
            phoneField.classList.remove('bg-error-container/20');
          }

          // Validate Email
          const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          if (!emailField.value.trim() || !emailRegex.test(emailField.value.trim())) {
            emailError.classList.remove('hidden');
            emailError.classList.add('flex');
            emailField.classList.add('bg-error-container/20');
            isValid = false;
          } else {
            emailError.classList.add('hidden');
            emailError.classList.remove('flex');
            emailField.classList.remove('bg-error-container/20');
          }

          if (!isValid) {
            const firstError = document.querySelector('.bg-error-container\\/20');
            if (firstError) {
              firstError.scrollIntoView({ behavior: 'smooth', block: 'center' });
              firstError.focus();
            }
            return;
          }

          form.submit();
          return;

          // Animate Submission and Toggle Confirmation
          submitBtn.disabled = true;
          submitBtn.innerHTML = '<span class="material-symbols-outlined animate-spin text-xl">progress_activity</span><span>PROCESSING RFQ...</span>';

          setTimeout(() => {
            // Populate summary card
            const selectedProduct = document.getElementById('product-category').value;
            const selectedMaterial = document.getElementById('material-type').value;
            
            summaryProduct.textContent = selectedProduct;
            summaryMaterial.textContent = selectedMaterial;
            summaryContact.textContent = emailField.value.trim() + ' (' + phoneField.value.trim() + ')';
            
            // Generate pseudo RFQ reference ID
            const randomId = Math.floor(1000 + Math.random() * 9000);
            dynamicRfqId.textContent = '#DSAM-RFQ-2026-' + randomId;

            formCard.classList.add('hidden');
            successContainer.classList.remove('hidden');
            successContainer.scrollIntoView({ behavior: 'smooth', block: 'start' });
          }, 600);
        });
      }

      // Reset Button Trigger
      if (resetBtn) {
        resetBtn.addEventListener('click', function() {
          form.reset();
          submitBtn.disabled = false;
          submitBtn.innerHTML = '<span class="tracking-wide">REQUEST A QUOTE</span><span class="material-symbols-outlined text-xl">send</span>';
          successContainer.classList.add('hidden');
          formCard.classList.remove('hidden');
          formCard.scrollIntoView({ behavior: 'smooth', block: 'start' });
        });
      }

      // File Removal / Replacement triggers
      if (removeFileBtn) {
        removeFileBtn.addEventListener('click', function() {
          previewCard.classList.add('hidden');
        });
      }

      if (replaceFileBtn && fileInput) {
        replaceFileBtn.addEventListener('click', function() {
          fileInput.click();
        });
      }

      if (fileInput) {
        fileInput.addEventListener('change', function(e) {
          if (this.files && this.files[0]) {
            previewCard.classList.remove('hidden');
            const fileNameElem = previewCard.querySelector('.font-semibold');
            if (fileNameElem) {
              fileNameElem.textContent = this.files[0].name;
            }
          }
        });
      }
    })();
  </script>
